#!/usr/bin/env bash
# ai_agents.sh — Count AI coding agents on a login node
# No sudo needed. Just run it.
# This was refactored and generated by Claude code from original bash command by Enrico Glerean
# The code was reviewed by Enrico Glerean

PS_SNAPSHOT=$(ps -eo pid=,user:32=,args= --no-headers 2>/dev/null)

# agent_label | extended-grep pattern (case-insensitive, first match wins)
AGENTS=(
  "Claude Code|claude|@anthropic|claude-code"
  "Codex (OpenAI)|codex"
  "Cursor|/\.cursor-server/bin/|(^|[[:space:]/])cursor-server([[:space:]]|$)"
  "GitHub Copilot|copilot|github\.copilot"
  "Antigravity (Google)|antigravity|/\.gemini/bin/agy([[:space:]]|$)"
  "Gemini CLI|(^|[[:space:]/])gemini([[:space:]]|$)|@google/gemini-cli"
  "OpenCode|(^|[[:space:]/])opencode([[:space:]]|$)"
  "Aider|aider"
  "Continue|continue-server|continue\.extensions"
  "Cody (Sourcegraph)|cody|sourcegraph\.cody"
  "Windsurf/Codeium|windsurf|codeium"
  "Amazon Q|amazon-q|aws-toolkit.*q"
  "Tabnine|tabnine"
  "Supermaven|supermaven"
  "Roo Code|roo-code|roocode"
  "Augment Code|augment-code|augmentcode"
  "JetBrains (Remote Dev)|JetBrains/RemoteDev|remote-dev-server\.sh"
  "Kilo Code|kilocode\.kilo-code|/kilo([[:space:]]|$)"
  "Mistral Vibe|mistralai\.mistral-vibe-code|vibe-acp"
  "Pi Coding Agent|(^|[[:space:]/])pi([[:space:]]|$)|pi-coding-agent"
  "Goose|(^|[[:space:]/])goose([[:space:]]|$)"
  "Kiro|(^|[[:space:]/])kiro([[:space:]]|$)|/\.kiro/"
)

# Refactored counting logic
declare -A AGENT_USERS AGENT_PROCS AGENT_CONTAINED


for entry in "${AGENTS[@]}"; do
    label="${entry%%|*}"
    AGENT_PROCS[$label]=0
    AGENT_CONTAINED[$label]=0
    AGENT_USERS[$label]=""
done

shopt -s nocasematch

while IFS= read -r line; do
    [[ -z "$line" ]] && continue
    read -r pid user cmd <<< "$line"

    for entry in "${AGENTS[@]}"; do
        label="${entry%%|*}"
        pattern="${entry#*|}"

        if [[ "$cmd" =~ $pattern ]]; then
            AGENT_PROCS[$label]=$(( ${AGENT_PROCS[$label]} + 1 ))
            AGENT_USERS[$label]+="$user"$'\n'
			if [[ -d "/proc/$pid/root/.singularity.d" ]]; then
				AGENT_CONTAINED[$label]=$(( ${AGENT_CONTAINED[$label]} + 1 ))
			fi
            break  # First match wins
        fi
    done
done <<< "$PS_SNAPSHOT"

shopt -u nocasematch

# ── Summary table ──────────────────────────────────────────────
echo ""
echo "  AI Coding Agents — $(hostname) — $(date '+%Y-%m-%d %H:%M')"
echo "  ─────────────────────────────────────────────────"
printf "  %-24s %6s %8s %14s\n" "Agent" "Users" "Procs" "ContainedProcs"
printf "  %-24s %6s %8s %14s\n" "────────────────────────" "──────" "────────" "──────────────"

total_users="" total_procs=0 total_contained=0

for entry in "${AGENTS[@]}"; do
  label="${entry%%|*}"
  procs=${AGENT_PROCS[$label]}
  contained=${AGENT_CONTAINED[$label]}
  if [[ $procs -gt 0 ]]; then
    ucount=$(echo -n "${AGENT_USERS[$label]}" | sort -u | grep -c . 2>/dev/null || echo 0)
  else
    ucount=0
  fi
  printf "  %-24s %6d %8d %14d\n" "$label" "$ucount" "$procs" "$contained"
  total_procs=$(( total_procs + procs ))
  total_contained=$(( total_contained + contained ))
  total_users+="${AGENT_USERS[$label]}"
done

total_unique=$(echo -n "$total_users" | sort -u | grep -c . 2>/dev/null || echo 0)
printf "  %-24s %6s %8s %14s\n" "────────────────────────" "──────" "────────" "──────────────"
printf "  %-24s %6d %8d %14d\n" "TOTAL" "$total_unique" "$total_procs" "$total_contained"

# ── Per-agent user breakdown ───────────────────────────────────
for entry in "${AGENTS[@]}"; do
  label="${entry%%|*}"
  [[ ${AGENT_PROCS[$label]} -eq 0 ]] && continue
  echo ""
  echo "  $label"
  echo -n "${AGENT_USERS[$label]}" | sort | uniq -c | sort -rn | \
    while read -r count user; do
      printf "    %-20s %3d procs\n" "$user" "$count"
    done
done

echo ""

# ── Potential YOLO / unrestricted approval modes (visible CLI flags only) ──
echo ""
echo "  AI agents with approval bypass — CLI flags only"
echo "  ───────────────────────────────────────────────"
YOLO_HITS=""
while IFS= read -r line; do
  read -r _pid user cmd <<< "$line"
  read -r exe opts <<< "$cmd"
  # Codex installed via npm often launches as: node /path/to/codex ...
  if [[ ${exe##*/} == node ]]; then
    read -r exe opts <<< "$opts"
  fi

  [[ $exe == */.claude/remote/ccd-cli/* ]] && exe=claude

  agent=""
  case "${exe##*/}" in
    claude)
      [[ $opts =~ (^|[[:space:]])--dangerously-skip-permissions([[:space:]]|$) ||
         $opts =~ (^|[[:space:]])--permission-mode(=|[[:space:]]+)bypassPermissions([[:space:]]|$) ]] && agent="Claude Code" ;;
    codex)
      [[ $opts =~ (^|[[:space:]])(--yolo|--dangerously-bypass-approvals-and-sandbox)([[:space:]]|$) ]] && agent="Codex"
      if [[ $opts =~ (^|[[:space:]])(--sandbox|-s)(=|[[:space:]]+)danger-full-access([[:space:]]|$) &&
            $opts =~ (^|[[:space:]])(--ask-for-approval|-a)(=|[[:space:]]+)never([[:space:]]|$) ]]; then
        agent="Codex"
      fi ;;
    gemini|qwen)
      [[ $opts =~ (^|[[:space:]])(--yolo|-y|--approval-mode(=|[[:space:]]+)yolo)([[:space:]]|$) ]] && agent="${exe##*/}" ;;
    copilot|copilot-runtime)
      [[ $opts =~ (^|[[:space:]])(--yolo|--allow-all|--allow-all-tools)([[:space:]]|$) ]] && agent="GitHub Copilot" ;;
    cursor-agent)
      [[ $opts =~ (^|[[:space:]])(--yolo|--force|-f)([[:space:]]|$) ]] && agent="Cursor" ;;
    opencode)
      [[ $opts =~ (^|[[:space:]])--auto([[:space:]]|$) ]] && agent="OpenCode" ;;
    aider)
      [[ $opts =~ (^|[[:space:]])--yes-always([[:space:]]|$) ]] && agent="Aider" ;;
    vibe|vibe-acp)
      [[ $opts =~ (^|[[:space:]])(--yolo|--auto-approve|--agent(=|[[:space:]]+)auto-approve)([[:space:]]|$) ]] && agent="Mistral Vibe" ;;
    kiro-cli)
      [[ $opts =~ (^|[[:space:]])--trust-all-tools([[:space:]]|$) ]] && agent="Kiro" ;;
    agy)
      [[ $opts =~ (^|[[:space:]])--dangerously-skip-permissions([[:space:]]|$) ]] && agent="Antigravity" ;;
  esac
  [[ -n $agent ]] && YOLO_HITS+="$user"$'\t'"$agent"$'\n'
done <<< "$PS_SNAPSHOT"

if [[ -n $YOLO_HITS ]]; then
  printf '    %-20s %s\n' 'User' 'Agent'
  printf '%s' "$YOLO_HITS" | sort -u | awk -F '\t' '{printf "    %-20s %s\n", $1, $2}'
else
  echo "    None detected"
fi

# ── Email batches for users running AI agents ──────────────────
echo ""
echo "  Email batches — manual sending"

for entry in "${AGENTS[@]}"; do
  label="${entry%%|*}"
  [[ ${AGENT_PROCS[$label]} -eq 0 ]] && continue

  users=$(printf '%s' "${AGENT_USERS[$label]}" |
    sed '/^$/d' | sort -u | paste -sd, - | sed 's/,/, /g')

  echo ""
  echo "  ── $label ──"
  echo "  Users: $users"

  cat <<EOF

Subject: Please use the dedicated Triton login node for AI agents

Hi,

We detected $label running under your account on the Triton login node triton.aalto.fi.

We have a separate login node for running coding agents at code.triton.aalto.fi. Could you move your workflow to the dedicated node?

Thanks!
Enrico

EOF
done
